import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"狼族少年","description":"","frontmatter":{},"headers":[],"relativePath":"表层/人物/狼族少年.md","filePath":"表层/人物/狼族少年.md","lastUpdated":1787066340000}'),i={name:"表层/人物/狼族少年.md"};function e(n,a,s,h,u,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="狼族少年" tabindex="-1">狼族少年 <a class="header-anchor" href="#狼族少年" aria-label="Permalink to &quot;狼族少年&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>种族</strong>：狼族</li><li><strong>性别</strong>：雄性</li><li><strong>年龄</strong>：青少年至青年（具体年龄随故事进展）</li><li><strong>当前状态</strong>：失忆状态，被拉斯塔在山洞中发现后带回红星孤儿院</li></ul><h2 id="外貌特征与形态" tabindex="-1">外貌特征与形态 <a class="header-anchor" href="#外貌特征与形态" aria-label="Permalink to &quot;外貌特征与形态&quot;">​</a></h2><ul><li><strong>毛色</strong>：灰黑色，带有少许红色花纹</li><li><strong>眼神</strong>：正常眼神，有时让人感觉诡异的空洞</li><li><strong>体型</strong>：符合狼族特征的青少年至青年体型</li><li><strong>服装</strong>：穿着红星孤儿院的简朴服装</li><li><strong>气质</strong>：沉默，与其他孤儿有距离感</li></ul><h2 id="背景简史-表层流传" tabindex="-1">背景简史（表层流传） <a class="header-anchor" href="#背景简史-表层流传" aria-label="Permalink to &quot;背景简史（表层流传）&quot;">​</a></h2><h3 id="出生与收养" tabindex="-1">出生与收养 <a class="header-anchor" href="#出生与收养" aria-label="Permalink to &quot;出生与收养&quot;">​</a></h3><ul><li><strong>出生不明</strong>：出生不明，具体出生时间、地点、父母均不可查</li><li><strong>南方狼村收养</strong>：被南方狼村收养，度过约十年幸福生活</li></ul><h3 id="狼灾时期-觉醒者传说" tabindex="-1">狼灾时期：觉醒者传说 <a class="header-anchor" href="#狼灾时期-觉醒者传说" aria-label="Permalink to &quot;狼灾时期：觉醒者传说&quot;">​</a></h3><ul><li><strong>奴隶官事件</strong>：黑暗时代约 180 年，被猪族奴隶官抓走，亲友在面前惨死</li><li><strong>起义与建国</strong>：屠戮奴隶厂、解放被囚禁的狼族，带领狼族建立初步的国家</li><li><strong>联合背刺</strong>：遭新五族中猪、虎、豹、蝠四族联合背刺，狼族死伤惨重</li><li><strong>四方巡游与消失</strong>：此后独自一人巡游大地四方，数年内灭绝猪、虎、豹、蝠四族，彻底改变大陆种族格局；在即将灭绝鹰族时突然消失</li></ul><h3 id="当前-失忆于红星孤儿院" tabindex="-1">当前：失忆于红星孤儿院 <a class="header-anchor" href="#当前-失忆于红星孤儿院" aria-label="Permalink to &quot;当前：失忆于红星孤儿院&quot;">​</a></h3><ul><li><strong>失忆状态</strong>：当前处于失忆状态，在红星孤儿院准备与拉斯塔一同冒险</li><li><strong>身份认知</strong>：对自己过去的身份完全不清楚，自认力量为普通魔法</li></ul><h2 id="人格特质" tabindex="-1">人格特质 <a class="header-anchor" href="#人格特质" aria-label="Permalink to &quot;人格特质&quot;">​</a></h2><ul><li><strong>沉默寡言</strong>：沉默，与其他孤儿有距离感</li><li><strong>狼族天性</strong>：如同狼族公众认知中的&quot;天真纯善&quot;，易信他人</li></ul><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与维斯塔-红星孤儿院院长" tabindex="-1">与维斯塔（红星孤儿院院长） <a class="header-anchor" href="#与维斯塔-红星孤儿院院长" aria-label="Permalink to &quot;与维斯塔（红星孤儿院院长）&quot;">​</a></h3><ul><li><strong>监护关系</strong>：当前维斯塔是其监护人</li><li><strong>教导</strong>：维斯塔教导其如何控制力量，并回答其提出的问题</li></ul><h3 id="与拉斯塔" tabindex="-1">与拉斯塔 <a class="header-anchor" href="#与拉斯塔" aria-label="Permalink to &quot;与拉斯塔&quot;">​</a></h3><ul><li><strong>孤儿院同伴</strong>：同为红星孤儿院的孤儿</li><li><strong>日常互动</strong>：有日常的互动和交流</li><li><strong>同伴感情</strong>：建立了同伴感情，是冒险路途上的伙伴</li></ul><h3 id="与狼族" tabindex="-1">与狼族 <a class="header-anchor" href="#与狼族" aria-label="Permalink to &quot;与狼族&quot;">​</a></h3><ul><li><strong>救世主身份</strong>：狼族的救世主、反抗象征、建国希望</li><li><strong>历史影响</strong>：其行动使狼族从奴隶种族走向独立</li></ul><hr><h2 id="真相档案" tabindex="-1">真相档案 <a class="header-anchor" href="#真相档案" aria-label="Permalink to &quot;真相档案&quot;">​</a></h2><blockquote><p>以上是表层生灵所能知晓的全部。此人的真实身份与完整档案（含大量剧透），见<a href="./../../中层/人物/狼族少年" class="layer-link" data-layer="中层">狼族少年（真相档案）</a>。</p></blockquote><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../种族/狼族">狼族</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./拉斯塔">拉斯塔</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./">众生录</a></li></ul><hr>',27)])])}const q=l(i,[["render",e]]);export{c as __pageData,q as default};
